# Пълен път: шофьор пише → админ отговаря → шофьор вижда; подреждане с влачене; роли; 2FA; промо; преглед като шофьор
import asyncio, re
from playwright.async_api import async_playwright

R=[]
def ok(n,c,x=''): R.append(f"{'PASS' if c else 'FAIL'}  {n}{'  ['+str(x)+']' if x!='' else ''}")
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); ctx = await b.new_context(viewport={'width':1280,'height':2000}); await ctx.add_init_script("try{localStorage.setItem('profitaxi.paidMode','1')}catch(e){}")
        await ctx.add_init_script("try{localStorage.setItem('profitaxi.adminTour','done');sessionStorage.setItem('profitaxi.oneIntro','1')}catch(e){}")
        base='http://localhost:8765'; errs=[]
        d = await ctx.new_page(); d.on('pageerror', lambda e: errs.append('drv:'+str(e)))
        await d.goto(base+'/app'); await d.evaluate('localStorage.clear()'); await d.goto(base+'/app#/login'); await d.wait_for_timeout(500)
        await d.fill('input[type=email]','ivan@demo.bg'); await d.fill('input[type=password]','demo123'); await d.click('button[type=submit]'); await d.wait_for_timeout(700)
        await d.keyboard.press('Escape'); await d.goto(base+'/app#/help'); await d.wait_for_timeout(500)
        await d.fill('textarea', 'Тест въпрос от Иван'); await d.click('text=Изпрати >> nth=0'); await d.wait_for_timeout(400)
        ok('Шофьорът изпраща въпрос', 'Тест въпрос от Иван' in await d.inner_text('#app'))
        await d.goto(base+'/app#/home'); await d.wait_for_timeout(400)
        a = await ctx.new_page(); a.on('pageerror', lambda e: errs.append('adm:'+str(e)))
        await a.goto(base+'/admin.html'); await a.wait_for_timeout(400)
        await a.fill('input[type=email]','admin@profitaxi.bg'); await a.fill('input[type=password]','admin123'); await a.click('button[type=submit]'); await a.wait_for_timeout(800)
        await a.evaluate("location.hash='#/messages?t=inbox'"); await a.wait_for_timeout(500)
        await a.click('.tk-row:has-text("Тест въпрос")'); await a.wait_for_timeout(400)
