        await d.goto(base+'/app#/home'); await d.wait_for_timeout(600)
        ok('Шофьорът вижда „Отговорихме ти“ на Днес', 'Отговорихме ти' in await d.inner_text('#app'))
        await d.goto(base+'/app#/help'); await d.wait_for_timeout(500)
