        await a.evaluate("location.hash='#/overview'"); await a.wait_for_timeout(600)
        first = await a.eval_on_selector('[data-zone="overview"]', 'z=>z.children[0].dataset.k')
        await a.click('#adm-arrange'); await a.wait_for_timeout(300)
