        await a.mouse.move(sb['x']+40, sb['y']+10); await a.mouse.down(); await a.mouse.move(sb['x']+60, sb['y']-30, steps=4)
        await a.mouse.move(db['x']+80, db['y']+10, steps=12); await a.mouse.up(); await a.wait_for_timeout(300)
