        ok('Влачене с мишката мести картата', now=='attention', f'{first} -> {now}')
        await a.click('.arr-bar >> text=Готово'); await a.reload(); await a.wait_for_timeout(800)
        ok('Подредбата се помни след презареждане', await a.eval_on_selector('[data-zone="overview"]', 'z=>z.children[0].dataset.k')=='attention')
        # Стрелки и скриване
        await a.click('#adm-arrange'); await a.wait_for_timeout(200)
